package com.x7x24.skills;
import org.junit.jupiter.api.Test;
import java.util.*;
import static com.x7x24.skills.SkillResolver.*;
import static org.junit.jupiter.api.Assertions.*;
class SkillResolverTest {
 final SkillResolver resolver=new SkillResolver();final Domain domain=new Domain("ws","project","node-1","role-binding","maker","dev.code");
 Version version(String id,String ver,List<Dependency> deps){return new Version(id,ver,"fixed instructions","digest-"+id+ver,deps,Map.of("style",new Parameter("STRING","plain",true)),Set.of());}
 Binding binding(String id,Scope scope,String target,String skill,String constraint,Enforcement enforcement,String condition,Map<String,Object> parameters){return new Binding(id,"ws","project",scope,target,null,skill,constraint,enforcement,condition,parameters);}
 @Test void fullDependencyClosureIsLockedAndConflictsFail(){var a=version("a","1.0.0",List.of(new Dependency("b","^2")));var b=version("b","2.1.0",List.of());var catalogue=Map.of("a@1.0.0",a,"b@2.1.0",b);var root=binding("a",Scope.PROJECT,null,"a","^1",Enforcement.REQUIRED,null,Map.of());var lock=resolver.resolve(domain,List.of(root),catalogue,Set.of());assertEquals(2,lock.skills().size());assertEquals(List.of("b@2.1.0"),lock.skills().getFirst().dependencies());assertThrows(IllegalStateException.class,()->resolver.resolve(domain,List.of(root,binding("b",Scope.PROJECT,null,"b","1.0.0",Enforcement.REQUIRED,null,Map.of())),catalogue,Set.of()));}
 @Test void parameterPrecedenceNeverLowersProjectObligations(){var catalogue=Map.of("a@1.0.0",version("a","1.0.0",List.of()));var project=binding("project",Scope.PROJECT,null,"a","^1",Enforcement.REQUIRED,"api",Map.of("style","project"));var node=binding("node",Scope.NODE_INSTANCE,"node-1","a","1.0.0",Enforcement.OPTIONAL,null,Map.of("style","node"));var lock=resolver.resolve(domain,List.of(project,node),catalogue,Set.of());assertEquals("node",lock.skills().getFirst().parameters().get("style"));var evaluation=resolver.evaluate(lock,new Facts(Map.of(),false,null),Set.of(),Set.of());assertTrue(evaluation.stream().anyMatch(e->e.bindingId().equals("project")&&e.state().equals("BLOCKED_MISSING_APPLICABILITY_EVIDENCE")));assertEquals(2,evaluation.size());}
 @Test void sameScopeConflictForbiddenParametersCyclesAndCrossProjectAreRejected(){var a=version("a","1.0.0",List.of());var catalogue=Map.of("a",a);var one=binding("one",Scope.PROJECT,null,"a","^1",Enforcement.REQUIRED,null,Map.of("style","one"));var two=binding("two",Scope.PROJECT,null,"a","^1",Enforcement.REQUIRED,null,Map.of("style","two"));assertThrows(IllegalStateException.class,()->resolver.resolve(domain,List.of(one,two),catalogue,Set.of()));assertThrows(IllegalStateException.class,()->resolver.resolve(domain,List.of(binding("bad",Scope.PROJECT,null,"a","^1",Enforcement.REQUIRED,null,Map.of("allowedTools",List.of("network")))),catalogue,Set.of()));assertThrows(IllegalStateException.class,()->resolver.resolve(new Domain("ws","other","node-1","role-binding","maker","dev.code"),List.of(one),catalogue,Set.of()));var cyclic=version("a","1.0.0",List.of(new Dependency("a","^1")));assertThrows(IllegalStateException.class,()->resolver.resolve(domain,List.of(one),Map.of("a",cyclic),Set.of()));}
 @Test void dependencyCapabilitiesAndRevocationsBlockTheRootObligation(){
  var root=version("root","1.0.0",List.of(new Dependency("dependency","1.0.0")));var dependency=new Version("dependency","1.0.0","instruction","digest",List.of(),Map.of(),Set.of("network"));var binding=binding("root",Scope.PROJECT,null,"root","1.0.0",Enforcement.REQUIRED,null,Map.of());var lock=resolver.resolve(domain,List.of(binding),Map.of("root",root,"dependency",dependency),Set.of());assertEquals("BLOCKED_CAPABILITY",resolver.evaluate(lock,new Facts(Map.of(),true,"evidence"),Set.of(),Set.of()).getFirst().state());assertEquals("BLOCKED_REVOKED",resolver.evaluate(lock,new Facts(Map.of(),true,"evidence"),Set.of("network"),Set.of("dependency@1.0.0")).getFirst().state());
 }
 @Test void notApplicableRequiresEvidenceAndRevocationBlocksNewExecution(){var root=binding("root",Scope.PROJECT,null,"a","^1",Enforcement.REQUIRED,"api",Map.of());var lock=resolver.resolve(domain,List.of(root),Map.of("a",version("a","1.0.0",List.of())),Set.of());assertEquals("NOT_APPLICABLE",resolver.evaluate(lock,new Facts(Map.of("api",false),true,"scope-digest"),Set.of(),Set.of()).getFirst().state());assertEquals("BLOCKED_REVOKED",resolver.evaluate(lock,new Facts(Map.of("api",true),true,"scope-digest"),Set.of(),Set.of("a@1.0.0")).getFirst().state());}
}
